import {useFeatureFlags, useSalesChannel} from '@smart/feature-app';
import {Tag} from '@smart/react-components';
import {useTranslations} from '@smart/react-utils';
import {SalesChannel} from '@smart/types';
import {Heading, Text} from '@smart/web-components';
import classNames from 'classnames';
import React from 'react';
import {usedFeatureFlags} from '../../constants/common';
import {useAppModelContext} from '../../hooks/use-app-model';
import styles from './price.module.scss';

type PriceProps = {
  label: string;
  labelSup?: string;
  price: string;
  priceSuffix?: React.ReactNode;
  vatLabel?: string;
  hasDiscount?: boolean;
  enablePcP?: boolean;
  discountPrice?: string;
  discountPercentage?: number;
  discountAmount?: string;
};

export const Price = ({
  label,
  labelSup,
  price,
  vatLabel,
  priceSuffix,
  hasDiscount,
  enablePcP,
  discountPrice,
  discountPercentage,
  discountAmount,
}: PriceProps) => {
  const {enabled: hasDiscountFlags} = useFeatureFlags(
    usedFeatureFlags.ENABLE_DISCOUNT_IN_SALES_TOOL,
  );
  const {appModel} = useAppModelContext();
  const salesChannel = useSalesChannel();
  const {t} = useTranslations(appModel.translations);
  const isDiscountApplicable =
    hasDiscountFlags &&
    hasDiscount &&
    discountPrice &&
    salesChannel !== SalesChannel.DEMO;
  const replacePricePlaceholder = (
    text: string,
    originalPrice?: string,
  ): React.ReactNode => {
    const parts = text.split(`{{price}}`);
    const template = t(`discount.tag`);
    const placeholder = `{{discountTagPrice}}`;

    const dynamicValue =
      t(`discount.usePercentageDiscount`) === `true`
        ? `-${discountPercentage ?? ``}%`
        : `${discountAmount ?? ``}`;
    const staticText = template.replace(placeholder, ``);
    const trimmedStaticText =
      staticText.length > 25
        ? staticText.slice(0, 25 - dynamicValue.length)
        : staticText;
    const displayTagText = template
      .replace(placeholder, dynamicValue)
      .replace(staticText, trimmedStaticText);
    return (
      <div className={styles.originalPriceContent}>
        <span>{parts[0]}</span>
        <Text tag="span" className={styles.originalPrice}>
          {originalPrice}
        </Text>
        <span className={styles.priceSuffix}>{parts[1]}</span>
        <Tag variant="brabus" className={styles.tag}>
          {displayTagText}
          <sup>{t(`discount.tagSuperscript`)}</sup>
        </Tag>
      </div>
    );
  };
  return (
    <div className={styles[`price`]}>
      <Text variant="paragraph-200">
        {isDiscountApplicable ? t(`discount.priceLabel`) : label}
        {labelSup && (
          <sup>
            {isDiscountApplicable
              ? t(`discount.priceLabelSuperscript`)
              : labelSup}
          </sup>
        )}
      </Text>
      <div
        className={classNames({
          [styles.discountContainer!]: isDiscountApplicable,
          [styles.pcpContent!]: enablePcP,
        })}
      >
        <div className={styles.row}>
          <Heading
            tag="span"
            variant="headline-functional-50"
            className={classNames(styles[`price-value`], {
              [styles.discount!]: isDiscountApplicable,
            })}
          >
            {price}
          </Heading>
          {priceSuffix && priceSuffix}
        </div>

        {vatLabel && (
          <Text
            tag="span"
            className={styles[`vat-label`]}
            variant="paragraph-100"
          >
            {vatLabel}
          </Text>
        )}
      </div>
      {isDiscountApplicable && (
        <>
          {replacePricePlaceholder(
            t(`discount.listPriceDiscription`),
            discountPrice,
          )}
        </>
      )}
    </div>
  );
};

