import {useFeatureFlags} from '@smart/feature-app';
import {Loader} from '@smart/web-components';
import React from 'react';
import {ProductType, usedFeatureFlags} from '../constants/common';
import {useProductModel} from '../hooks/use-product-model';
import {AccessorySummary} from './accessory-summary';
import styles from './app.module.scss';
import {ExtendedConnectedServiceSummary} from './extended-connected-service-summary';
import {ExtendedWarrantySummary} from './extended-warranty-summary';
import {NotFound} from './not-found';
import {ProductHeader} from './product-header';
import {VehicleSummary} from './vehicle-summary';
import {WallboxSummary} from './wallbox-summary';
export const ProductSummary = () => {
  const {product, loading} = useProductModel();
  const {enabled: isExtendedWarrantyEnabled} = useFeatureFlags(
    usedFeatureFlags.ENABLE_EXTENDED_WARRANTY,
  );

  if (loading) {
    return <Loader size="medium" messageId="" className={styles.loader} />;
  }

  if (!product) {
    return (
      <>
        <ProductHeader />
        <NotFound />
      </>
    );
  }

  return (
    <>
      {isExtendedWarrantyEnabled &&
        product.productType === ProductType.EXTENDED_WARRANTY && (
          <ExtendedWarrantySummary productModel={product} />
        )}
      {product.productType === ProductType.ACCESSORY && (
        <AccessorySummary productModel={product} />
      )}
      {product.productType === ProductType.WALLBOX && (
        <WallboxSummary productModel={product} />
      )}
      {product.productType === ProductType.VEHICLE && (
        <VehicleSummary productModel={product} />
      )}
      {product.productType === ProductType.EXTENDED_CONNECTED_SERVICE && (
        <ExtendedConnectedServiceSummary productModel={product} />
      )}
    </>
  );
};

